1	// Plain (non-"use server") module: shared types for the in-portal file manager.
2	// A "use server" file may ONLY export async functions — exporting the FileEntry
3	// type from lib/actions-files.ts triggered Next's
4	// "A 'use server' file can only export async functions, found object" error when
5	// the Files tab invoked a server action, so the type lives here and is imported
6	// (as a type) by both the server actions and the FileManager client component.
7	
8	export type FileEntry = {
9	  name: string;
10	  isDirectory: boolean;
11	  size: number;
12	  modifiedMs: number;
13	  /** Octal permission string like "755", or null if unknown. */
14	  mode: string | null;
15	};
16

1	/**
2	 * Shared-hosting primitives (Phase 1 foundation).
3	 *
4	 * Pure, framework-free helpers the account lifecycle is built on — unit-tested so
5	 * the parts that end up in a shell command on a MULTI-TENANT box (a username, a
6	 * quota, a domain in an nginx `server_name`) are provably well-formed before they
7	 * ever get there. On a shared box a single bad interpolation is not one
8	 * customer's bug, it is everyone's; these validators are the first line of that.
9	 */
10	
11	/** A syntactically valid domain for a name-based vhost (no scheme, no path). */
