35	/**
36	 * A safe jailed Linux username for an account, derived deterministically and kept
37	 * short (Linux caps usernames at 32 chars; some tooling chokes past 16). Starts
38	 * with a letter, lowercase alnum only — nothing a shell could ever interpret.
39	 *
40	 * `seed` (email localpart or account id) proposes a readable base; `disambiguator`
41	 * (a slice of the account id) guarantees per-node uniqueness without a DB probe.
42	 * The result still has to pass `isValidUnixUsername` before use, and the caller
43	 * resolves any residual collision against the DB (`@@unique([hostingNodeId, username])`).
44	 */
45	export function deriveUsername(seed: string, disambiguator: string): string {
46	  const base = String(seed ?? "")
47	    .toLowerCase()
48	    .replace(/[^a-z0-9]/g, "")
49	    .replace(/^[0-9]+/, "") // must not start with a digit
50	    .slice(0, 8);
51	  const suffix = String(disambiguator ?? "")
52	    .toLowerCase()
53	    .replace(/[^a-z0-9]/g, "")
54	    .slice(0, 6);
55	  // Guarantee a non-empty body so the result always clears the min-length rule
56	  // even when both inputs sanitise away to nothing.
57	  const body = `${base}${suffix}` || "acct";
58	  return `nx${body}`.slice(0, 16);
59	}
