97	/** Disk quota in KB blocks for `setquota` (1 GB = 1,048,576 one-KB blocks). */
98	export function diskQuotaBlocks(diskGB: number): number {
99	  return Math.max(1, Math.floor(diskGB)) * 1024 * 1024;
100	}
