102	/**
103	 * Inode (file-count) quota for `setquota`, the containment for a DoS the block
104	 * quota alone doesn't stop: a tenant creating MILLIONS of tiny files exhausts the
105	 * shared filesystem's inode table — filling no disk blocks but breaking every
106	 * neighbour's ability to create a file. `setquota … <isoft> <ihard>` of `0 0`
107	 * means UNLIMITED inodes, so a real cap is required here. Scales gently off the
108	 * plan's disk size but is floored (a 1 GB plan still gets working room) and
109	 * ceilinged (a huge plan can't effectively uncap); hard carries 25% headroom
110	 * over soft so a tenant hits the soft warning before the hard wall.
111	 */
112	export function diskQuotaInodes(diskGB: number): { soft: number; hard: number } {
113	  const gb = Math.max(1, Math.floor(diskGB || 1));
114	  const soft = Math.min(2_000_000, Math.max(200_000, gb * 50_000));
115	  const hard = Math.floor(soft * 1.25);
116	  return { soft, hard };
117	}
