186	/**
187	 * True for a well-formed 5-field cron schedule ("m h dom mon dow"). Each field is
188	 * restricted to the digits/ranges/steps/lists/`*` cron uses — nothing that could
189	 * be a shell metacharacter — so the schedule is safe to write into a crontab.
190	 * (Named shortcuts like @daily are intentionally NOT accepted here.)
191	 */
192	const CRON_FIELD_RE = /^[0-9*/,\-]+$/;
193	export function isValidCronSchedule(schedule: string): boolean {
194	  const parts = String(schedule ?? "").trim().split(/\s+/);
195	  if (parts.length !== 5) return false;
196	  return parts.every((p) => p.length > 0 && p.length <= 40 && CRON_FIELD_RE.test(p));
197	}
