199	/**
200	 * True for a cron command safe to place in a crontab line. It runs AS the jailed
201	 * user (crontab -u <user>), so it is already confined; the only invariants we
202	 * enforce here protect our own crontab writer: no newlines (one line per job) and
203	 * no `%` (cron's literal-newline metacharacter), and a sane length.
204	 */
205	export function isValidCronCommand(command: string): boolean {
206	  const c = String(command ?? "");
207	  if (c.length < 1 || c.length > 500) return false;
208	  return !/[\n\r%]/.test(c);
209	}
