211	/* ------------------------------------------------------------------------- *
212	 * Provisioner hardening (config generators for NEW accounts)
213	 *
214	 * These are the security-critical config the provisioner writes onto a
215	 * MULTI-TENANT box. They are pure + unit-tested here because a subtle gap in
216	 * any of them (a missing dangerous PHP function, a world-readable webroot, an
217	 * un-escaped GRANT wildcard) is not one customer's bug — it is a cross-tenant
218	 * breach. worker/hosting.ts imports these; it never re-derives them inline.
219	 * ------------------------------------------------------------------------- */
220	
221	/**
222	 * PHP functions blocked in every account's FPM pool (`disable_functions`).
223	 *
224	 * On a shared box `disable_functions` is a real isolation control, not defence
225	 * in depth: without it a tenant's PHP can shell out (`exec`/`system`), fork out
226	 * of `open_basedir` (`pcntl_exec` — compiled into PHP, so it bypasses a naive
227	 * blocklist), rewrite its own env (`putenv` → `LD_PRELOAD`/`GCONV_PATH`
228	 * tricks), plant symlinks that escape the jail (`symlink`/`link`), or reach the
229	 * host via `ffi`/`dl`. Everything a tenant could use to break out of its pool
230	 * belongs here. Kept sorted-by-purpose + deduped.
231	 */
232	export const PHP_DISABLED_FUNCTIONS: readonly string[] = [
233	  // Command execution — the classic RCE surface.
234	  "exec", "passthru", "shell_exec", "system", "proc_open", "popen",
235	  // Process control — pcntl_exec is compiled in and bypasses the above blocklist;
236	  // fork/signal/proc_nice let a tenant escape open_basedir or starve neighbours.
237	  "pcntl_exec", "pcntl_fork", "pcntl_signal", "proc_nice",
238	  // Environment + dynamic loading — putenv enables LD_PRELOAD-style escapes,
239	  // dl/ffi load native code straight past the PHP sandbox.
240	  "putenv", "dl", "ffi",
241	  // Filesystem jail-breaks — symlink/link can point out of open_basedir.
242	  "symlink", "link",
243	  // Mail — a shared box is a prized spam relay. mail() is blocked; mb_send_mail
244	  // is an equivalent wrapper, and imap_open/imap_mail can send too — block all.
245	  "mail", "mb_send_mail", "imap_open", "imap_mail",
246	  // Misc host-reach / info-leak vectors.
247	  "error_log", "curl_multi_exec", "parse_ini_file", "show_source",
248	] as const;
249	
250	/** The comma-separated `disable_functions` value for a pool config. */
251	export function phpDisableFunctions(): string {
252	  return [...PHP_DISABLED_FUNCTIONS].join(",");
253	}
