255	/**
256	 * Filesystem ownership + permission plan for a new account.
257	 *
258	 * The isolation goal: nginx (www-data) must serve a tenant's files, but a
259	 * NEIGHBOURING tenant (its own jailed unix user) must not be able to read them
260	 * — so nothing here is world-readable (the old `755` webroot let any tenant
261	 * read a peer's wp-config.php if open_basedir was ever escaped).
262	 *
263	 *  - home    `711 root:root` — chroot-safe (root-owned, no group/other write)
264	 *            and world-traversable so nginx can *reach* the webroot, but NOT
265	 *            world-listable, so a peer can't enumerate the home.
266	 *  - webroot `2750 <user>:www-data` — owner (the tenant's FPM pool) read/write,
267	 *            group www-data (nginx) read, world nothing. The setgid bit makes
268	 *            files the tenant creates inherit the www-data group so nginx keeps
269	 *            serving them; peers (neither owner nor in www-data) are shut out.
270	 *  - tmp     `700 <user>:<user>` — private PHP scratch (upload/session dir).
271	 *
272	 * nginx reaches tenant files via GROUP membership (www-data owns the webroot
273	 * group), never via world bits — that is the whole point of dropping 755.
274	 */
275	export function accountFsPlan(username: string): {
276	  home: { owner: string; mode: string };
277	  webroot: { owner: string; mode: string };
278	  tmp: { owner: string; mode: string };
279	  nginxGroup: string;
280	} {
281	  return {
282	    home: { owner: "root:root", mode: "711" },
283	    webroot: { owner: `${username}:www-data`, mode: "2750" },
284	    tmp: { owner: `${username}:${username}`, mode: "700" },
285	    nginxGroup: "www-data",
286	  };
287	}
