289	/** PHP-FPM pool hardening limits applied to every account pool. */
290	export const FPM_MEMORY_LIMIT = "256M";
291	export const FPM_REQUEST_TERMINATE_TIMEOUT = "120s";
292	
293	/**
294	 * The per-account PHP-FPM pool config (the PHP isolation boundary). Pure: given
295	 * the validated username + jailed paths, returns the exact pool file contents.
296	 *
297	 * open_basedir is scoped to the account home (+ the shared PHP lib) and NO
298	 * LONGER includes `/tmp`: PHP's tmp/session dirs are redirected into the home,
299	 * so a world-writable `/tmp` on open_basedir was just an unnecessary shared
300	 * surface between tenants. memory_limit + request_terminate_timeout cap a
301	 * single tenant from exhausting the shared box.
302	 */
303	export function fpmPoolConfig(username: string, home: string, webroot: string): string {
304	  const sock = `/run/php/${username}.sock`;
305	  return [
306	    `[${username}]`,
307	    `user = ${username}`,
308	    `group = ${username}`,
309	    `listen = ${sock}`,
310	    `listen.owner = ${username}`,
311	    `listen.group = www-data`,
312	    `pm = ondemand`,
313	    `pm.max_children = 6`,
314	    `pm.process_idle_timeout = 30s`,
315	    `chdir = ${webroot}`,
316	    // TRAILING SLASHES are load-bearing: `${home}` (no slash) would also authorise
317	    // `${home}2/…` — a sibling tenant's home — so open_basedir must pin the prefix
318	    // to the directory itself via the trailing `/` (same for the shared PHP lib).
319	    `php_admin_value[open_basedir] = ${home}/:/usr/share/php/`,
320	    `php_admin_value[disable_functions] = ${phpDisableFunctions()}`,
321	    `php_admin_value[memory_limit] = ${FPM_MEMORY_LIMIT}`,
322	    `php_admin_value[request_terminate_timeout] = ${FPM_REQUEST_TERMINATE_TIMEOUT}`,
323	    `php_admin_value[upload_tmp_dir] = ${home}/tmp`,
324	    `php_admin_value[session.save_path] = ${home}/tmp`,
325	  ].join("\n");
326	}
