328	/**
329	 * Escape a MySQL identifier for the `ON <db>.*` clause of a GRANT.
330	 *
331	 * In GRANT, `_` and `%` are LIKE-wildcards: an un-escaped grant on `nxuser_wp`
332	 * silently also grants on `nxuserXwp`, `nxuser_wpZ`, … i.e. a neighbouring
333	 * tenant's database. Escaping them (and the escape char itself) with a
334	 * backslash pins the grant to exactly one database.
335	 */
336	export function escapeGrantDbName(name: string): string {
337	  return name.replace(/([\\_%])/g, "\\$1");
338	}
339	
340	/**
341	 * The scoped SQL that creates one account database + user and grants that user
342	 * privileges on THAT DATABASE ONLY.
343	 *
344	 * Security invariants (audited): the GRANT is pinned to the exact db via
345	 * escapeGrantDbName (no wildcard bleed into a peer's db), it is NEVER `*.*`,
346	 * and `ALL PRIVILEGES` at database scope confers no global FILE/SUPER (those
347	 * are server-level and cannot be granted by a db-scoped GRANT). Returns plain
348	 * SQL with real backticks; the caller shell-escapes for `mysql -e`.
349	 */
350	export function buildScopedGrantSql(dbName: string, dbUser: string, dbPass: string): string {
351	  const grantName = escapeGrantDbName(dbName);
352	  return (
353	    `CREATE DATABASE IF NOT EXISTS \`${dbName}\`; ` +
354	    `CREATE USER IF NOT EXISTS '${dbUser}'@'localhost' IDENTIFIED BY '${dbPass}'; ` +
355	    `GRANT ALL PRIVILEGES ON \`${grantName}\`.* TO '${dbUser}'@'localhost'; ` +
356	    `FLUSH PRIVILEGES;`
357	  );
358	}
