362	/** The account-level MySQL user the in-portal DB manager authenticates as. One
363	 *  per account, derived from the (already shell/SQL-safe) username. Kept <=32
364	 *  chars — MySQL's user-name limit. Usernames are `[a-z][a-z0-9]{2,31}` (no
365	 *  underscore), so `<username>_mgr` is unambiguous and never collides with a
366	 *  per-database user (`<username>_<slug>`) whose slug can't be the reserved
367	 *  literal `mgr` used here… — we simply reserve this name for the manager. */
368	export function dbMgrUserFor(username: string): string {
369	  return `${username}_mgr`.slice(0, 32);
370	}
371	
372	/** Is this a syntactically valid MySQL account/database identifier for OUR
373	 *  generated names? Deliberately strict — only the charset our provisioner ever
374	 *  produces (`<username>_<slug>` / `<username>_mgr`), so a value that reaches the
375	 *  `mysql` command line as a flag can carry no shell metacharacters. NOT for
376	 *  arbitrary user-supplied table names (those are validated by membership against
377	 *  SHOW TABLES + backtick-quoting, never interpolated into a shell). */
378	const DB_IDENT_RE = /^[a-z0-9_]{1,64}$/;
379	export function isValidDbIdentifier(name: string): boolean {
380	  return DB_IDENT_RE.test(String(name ?? ""));
381	}
382	
383	/**
384	 * The grant that scopes the DB-manager user to EXACTLY this account's own
385	 * databases and nothing else. The privilege target is `<username>\_%`.* — the
386	 * account username, a LITERAL underscore (escaped so it is not a LIKE wildcard),
387	 * then `%`. That matches every `<username>_<...>` database the account can create
388	 * and, because usernames are `[a-z][a-z0-9]{2,31}` (never contain `_`), can never
389	 * match another tenant's `<otheruser>_<...>` databases — the same escaped-glob
390	 * boundary the backup/terminate paths already rely on.
391	 *
392	 * Security invariants (mirror buildScopedGrantSql): the grant is db-scoped, never
393	 * `*.*`, so `ALL PRIVILEGES` here confers NO server-level FILE/PROCESS/SUPER — the
394	 * manager user therefore cannot read files (LOAD_FILE/INTO OUTFILE), see other
395	 * connections, or touch the `mysql`/system schemas. Returns plain SQL with real
396	 * backticks; the caller shell-escapes for `mysql -e`.
397	 */
398	export function buildDbMgrGrantSql(username: string, mgrUser: string, mgrPass: string): string {
399	  // `${username}\_%` — escape only the underscore (username itself is [a-z0-9]).
400	  const scope = `${username}\\_%`;
401	  return (
402	    `CREATE USER IF NOT EXISTS '${mgrUser}'@'localhost' IDENTIFIED BY '${mgrPass}'; ` +
403	    `ALTER USER '${mgrUser}'@'localhost' IDENTIFIED BY '${mgrPass}'; ` +
404	    `GRANT ALL PRIVILEGES ON \`${scope}\`.* TO '${mgrUser}'@'localhost'; ` +
405	    `FLUSH PRIVILEGES;`
406	  );
407	}
