343	export async function createHostingDatabase(accountId: string, label: string): Promise<{ error?: string; ok?: boolean; password?: string }> {
344	  const user = await requireUser();
345	  await assertNotImpersonating();
346	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { id: true, userId: true, status: true, username: true, maxDatabases: true } });
347	  if (!a) return { error: "Account not found." };
348	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
349	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
350	  // A short, safe suffix keyed off the account username: <user>_<slug>.
351	  const slug = String(label ?? "").toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 12) || "db";
352	  const name = `${a.username}_${slug}`.slice(0, 64);
353	  const dbUser = name.slice(0, 32);
354	  if (!/^[a-z0-9_]{1,64}$/.test(name)) return { error: "Invalid database name." };
355	  const password = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
356	  // Count + create in ONE serializable transaction, so concurrent creates can't
357	  // both read a stale count and blow past the plan cap (audit 2026-08-01 TOCTOU).
358	  try {
