432	  // A DONE result may carry a one-time secret (WordPress admin pw). Return it once,
433	  // then clear it so it isn't shown again on the next poll.
434	  const out = rows.map((t) => ({ id: t.id, kind: t.kind, status: t.status, result: t.result, error: t.error, createdAt: t.createdAt.toISOString() }));
