234	/**
235	 * Upload a single file from the browser to the customer's server over SFTP,
236	 * landing it under {@link UPLOAD_DIR} with a sanitized basename, and return the
237	 * absolute remote path so the caller can reference it (e.g. type it into the
238	 * `claude` CLI, which reads file/image paths).
239	 *
240	 * SECURITY. Like every action here it `requireUser()`s + ownership-checks the
241	 * target server INSIDE the function (via `ownedServer`, which enforces
242	 * `userId === caller` unless admin) before any credential is touched, so a
243	 * caller can never write onto another tenant's box. The destination is fixed to
244	 * UPLOAD_DIR + a `validateName`d basename — a path-traversal write is
245	 * structurally impossible. Size is capped both before and after base64 decode.
246	 *
247	 * `base64` accepts either a raw base64 string or a `data:...;base64,<payload>`
248	 * data URL (the shape a browser FileReader / paste produces).
249	 */
250	export async function uploadToServer(
251	  serverId: string,
252	  filename: string,
253	  base64: string
254	): Promise<{ ok: true; path: string; name: string } | { ok: false; error: string }> {
255	  try {
256	    const { user, server } = await ownedServer(serverId);
257	    const limited = throttle(user.id, "upload", 30);
258	    if (limited) return { ok: false, error: limited };
259	
260	    if (typeof base64 !== "string" || base64.length === 0) {
261	      return { ok: false, error: "No file data was provided." };
262	    }
263	    // Accept a data: URL payload OR a bare base64 string.
264	    const comma = base64.indexOf(",");
265	    const payload = base64.startsWith("data:") && comma !== -1 ? base64.slice(comma + 1) : base64;
266	    // Cheap size guard BEFORE decoding: base64 inflates bytes by ~4/3.
267	    if (payload.length > Math.ceil((MAX_UPLOAD_BYTES * 4) / 3) + 8) {
268	      return { ok: false, error: "File exceeds the 15 MB upload limit." };
269	    }
270	
271	    const buffer = Buffer.from(payload, "base64");
272	    if (buffer.length === 0) return { ok: false, error: "The file is empty or could not be decoded." };
273	    if (!Number.isFinite(buffer.length) || buffer.length > MAX_UPLOAD_BYTES) {
274	      return { ok: false, error: "File exceeds the 15 MB upload limit." };
275	    }
276	
277	    const name = sanitizeUploadName(filename);
278	    const remotePath = joinPath(UPLOAD_DIR, name);
279	
280	    // Ensure the uploads dir exists (best-effort: a pre-existing dir is fine;
281	    // the write below is the authoritative op and surfaces any real failure).
282	    try {
283	      await mkdirPath(server, UPLOAD_DIR);
284	    } catch {
285	      /* already exists / benign — the write will fail loudly if not */
286	    }
287	    await writeFileBuffer(server, remotePath, buffer);
288	    return { ok: true, path: remotePath, name };
289	  } catch (err) {
290	    return { ok: false, error: safeError(err) };
291	  }
292	}
