79	/** Alphanumeric password (shell/SQL-safe: no quoting hazards). */
80	function strongPassword(len = 22): string {
81	  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
82	  const bytes = randomBytes(len);
83	  let out = "";
84	  for (let i = 0; i < len; i++) out += alphabet[bytes[i] % alphabet.length];
85	  return out;
86	}
