88	async function connectNode(node: { sshHost: string; sshPort: number; rootPasswordEnc: string | null }): Promise<Client> {
89	  const password = node.rootPasswordEnc ? decryptSecret(node.rootPasswordEnc) : "";
90	  if (!password) throw new Error("Hosting node has no root credential on record.");
91	  const conn = new Client();
92	  await new Promise<void>((resolve, reject) => {
93	    const timer = setTimeout(() => { try { conn.end(); } catch { /* */ } reject(new Error("SSH connect timed out")); }, CONNECT_TIMEOUT_MS);
94	    conn
95	      .on("ready", () => { clearTimeout(timer); resolve(); })
96	      .on("error", (e) => { clearTimeout(timer); reject(e); })
97	      .connect({ host: node.sshHost, port: node.sshPort, username: "root", password, readyTimeout: CONNECT_TIMEOUT_MS });
98	  });
99	  return conn;
100	}
