102	function exec(conn: Client, command: string, timeoutMs = STEP_TIMEOUT_MS): Promise<{ code: number; out: string }> {
103	  return new Promise((resolve, reject) => {
104	    const timer = setTimeout(() => reject(new Error("command timed out")), timeoutMs);
105	    conn.exec(command, (err, stream) => {
106	      if (err) { clearTimeout(timer); return reject(err); }
107	      let out = "";
108	      stream
109	        .on("close", (code: number) => { clearTimeout(timer); resolve({ code: code ?? 0, out }); })
110	        .on("data", (d: Buffer) => { out += d.toString(); })
111	        .stderr.on("data", (d: Buffer) => { out += d.toString(); });
112	    });
113	  });
114	}
