121	/**
122	 * The name-based nginx vhost for one account. It ALWAYS emits a `listen 443 ssl`
123	 * server block so nginx answers HTTPS from the moment the account exists —
124	 * `ssl.certDir` is the real Let's Encrypt live dir when `ssl.real` is true, else
125	 * the per-account SELF-SIGNED fallback generated at provision time. That is the
126	 * whole "clean setup always" guarantee: HTTPS shows a cert WARNING, never
127	 * ERR_CONNECTION_REFUSED. The HTTP→HTTPS redirect fires ONLY once a real cert
128	 * exists; a self-signed site still serves its body over both 80 and 443 (so it
129	 * can't 301-loop a visitor into an untrusted-cert dead end). Shared IP; routed
130	 * purely by server_name; PHP proxied to THIS account's socket only, root jailed to
131	 * its webroot. Pure string — no interpolation reaches a shell here.
132	 */
133	function renderHostingVhost(username: string, domain: string, webroot: string, sock: string, ssl: { certDir: string; real: boolean }): string {
134	  const phpLoc = [
135	    `    location ~ \\.php$ {`,
136	    `        include fastcgi_params;`,
137	    `        fastcgi_pass unix:${sock};`,
138	    `        fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;`,
139	    `    }`,
140	  ].join("\n");
141	  const body = [
142	    `    root ${webroot};`,
143	    // Refuse to follow a symlink whose target isn't owned by the same user as the
144	    // link — blocks a tenant symlinking to a victim's wp-config.php that nginx
145	    // (www-data) would otherwise happily serve (cross-tenant read, audit CRITICAL-1).
146	    `    disable_symlinks if_not_owner;`,
147	    `    index index.php index.html;`,
148	    `    location / { try_files $uri $uri/ /index.php?$query_string; }`,
149	    phpLoc,
150	    `    location ~ /\\. { deny all; }`,
151	  ].join("\n");
152	  const http = [
153	    `server {`,
154	    `    listen 80;`,
155	    `    listen [::]:80;`,
156	    `    server_name ${domain} www.${domain};`,
157	    `    location ^~ /.well-known/acme-challenge/ { root /var/www/html; }`,
158	    // Redirect to HTTPS only with a REAL cert; a self-signed site serves over 80 too.
159	    ssl.real ? `    location / { return 301 https://$host$request_uri; }` : body,
160	    `}`,
161	  ].join("\n");
162	  const https = [
163	    `server {`,
164	    `    listen 443 ssl;`,
165	    `    listen [::]:443 ssl;`,
166	    `    server_name ${domain} www.${domain};`,
167	    `    ssl_certificate ${ssl.certDir}/fullchain.pem;`,
168	    `    ssl_certificate_key ${ssl.certDir}/privkey.pem;`,
169	    `    ssl_protocols TLSv1.2 TLSv1.3;`,
170	    body,
171	    `}`,
172	  ].join("\n");
173	  return `${http}\n${https}\n`;
174	}
