184	 * A single extra site (subdomain / addon domain): its own docroot + PHP socket,
185	 * one `server_name`. Same shape as renderHostingVhost but keyed on an explicit
186	 * server_name string so it can serve a subdomain OR an addon domain. Pure — no
187	 * interpolation reaches a shell here (the caller validated every part).
188	 */
189	function renderSiteVhost(serverName: string, docroot: string, sock: string, sslLiveDir: string | null): string {
190	  const phpLoc = [
191	    `    location ~ \\.php$ {`,
192	    `        include fastcgi_params;`,
193	    `        fastcgi_pass unix:${sock};`,
194	    `        fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;`,
195	    `    }`,
196	  ].join("\n");
197	  const body = [
198	    `    root ${docroot};`,
199	    // Refuse a symlink whose target isn't owned by the link's owner — a tenant
200	    // can't symlink a neighbour's file into a served path (audit CRITICAL-1).
201	    `    disable_symlinks if_not_owner;`,
202	    `    index index.php index.html;`,
203	    `    location / { try_files $uri $uri/ /index.php?$query_string; }`,
204	    phpLoc,
205	    `    location ~ /\\. { deny all; }`,
206	  ].join("\n");
207	  const http = [
208	    `server {`,
209	    `    listen 80;`,
210	    `    listen [::]:80;`,
211	    `    server_name ${serverName};`,
212	    `    location ^~ /.well-known/acme-challenge/ { root /var/www/html; }`,
213	    sslLiveDir ? `    location / { return 301 https://$host$request_uri; }` : body,
214	    `}`,
215	  ].join("\n");
216	  if (!sslLiveDir) return http + "\n";
217	  const https = [
218	    `server {`,
219	    `    listen 443 ssl;`,
220	    `    listen [::]:443 ssl;`,
221	    `    server_name ${serverName};`,
222	    `    ssl_certificate ${sslLiveDir}/fullchain.pem;`,
223	    `    ssl_certificate_key ${sslLiveDir}/privkey.pem;`,
224	    `    ssl_protocols TLSv1.2 TLSv1.3;`,
225	    body,
226	    `}`,
227	  ].join("\n");
228	  return `${http}\n${https}\n`;
229	}
