254	/**
255	 * The isolation shell for one account (HTTP-only vhost; SSL added later by the
256	 * sweep once DNS points at us). Every interpolated value has already cleared a
257	 * validator, so nothing here can be a shell metacharacter.
258	 */
259	async function applyIsolation(
260	  conn: Client,
261	  a: { username: string; primaryDomain: string; diskQuotaMB: number; sftpPassword: string },
262	  php: string,
263	): Promise<void> {
264	  const u = a.username;
265	  const d = a.primaryDomain;
266	  if (!isValidUnixUsername(u)) throw new Error(`refusing unsafe username ${u}`);
267	  if (!isValidHostingDomain(d)) throw new Error(`refusing unsafe domain ${d}`);
268	  if (!/^\d\.\d$/.test(php)) throw new Error(`refusing unsafe php version ${php}`);
269	  const { home, webroot } = accountPaths(u);
270	  const quotaGB = Math.max(1, Math.round(a.diskQuotaMB / 1024));
271	  const hardBlocks = diskQuotaBlocks(quotaGB);
272	  const softBlocks = Math.floor(hardBlocks * 0.95);
273	  const inodes = diskQuotaInodes(quotaGB);
274	  const sock = `/run/php/${u}.sock`;
275	
276	  // 1. Jailed user. Home is ROOT-owned (a chroot requirement); the user owns only
277	  //    public_html + tmp under it. nologin shell — SFTP-only via the chroot below.
278	  //
279	  // Perms come from the tested accountFsPlan(): home 711 (chroot-safe + nginx can
280	  // TRAVERSE to the webroot but a peer tenant can't LIST the home), webroot
281	  // 2750 <user>:www-data (nginx reads via the www-data GROUP, never world — the
282	  // old world-readable 755 let any tenant read a neighbour's wp-config.php if
283	  // open_basedir was escaped; the setgid bit keeps tenant-created files in the
284	  // www-data group so nginx keeps serving them), tmp 700 (private PHP scratch).
285	  const fs = accountFsPlan(u);
286	  await run(conn, "create user", `id -u ${u} >/dev/null 2>&1 || useradd -m -d ${home} -s /usr/sbin/nologin ${u}`);
287	  await run(
288	    conn,
289	    "chroot-safe home",
290	    `mkdir -p ${webroot} ${home}/tmp && ` +
291	      `chown ${fs.home.owner} ${home} && chmod ${fs.home.mode} ${home} && ` +
292	      `chown ${fs.webroot.owner} ${webroot} && chmod ${fs.webroot.mode} ${webroot} && ` +
293	      `chown ${fs.tmp.owner} ${home}/tmp && chmod ${fs.tmp.mode} ${home}/tmp`,
294	  );
295	  await run(conn, "sftp password", `printf '%s:%s' ${u} '${a.sftpPassword}' | chpasswd`);
296	
297	  // 2. Disk quota (fs must have usrquota — node onboarding enables it). The last
298	  //    two fields are the INODE soft/hard limits: `0 0` = unlimited inodes, which
299	  //    let a tenant exhaust the shared filesystem's inode table with millions of
300	  //    tiny files (a DoS the block quota can't stop), so we pass real caps (HIGH-2).
301	  await run(conn, "disk quota", `command -v setquota >/dev/null 2>&1 && setquota -u ${u} ${softBlocks} ${hardBlocks} ${inodes.soft} ${inodes.hard} /home || echo 'quota tool absent — skipped'`);
302	
303	  // 3. Per-user PHP-FPM pool — THE PHP isolation boundary.
304	  await writeFpmPool(conn, u, home, webroot, php);
305	
306	  // 4. Self-signed FALLBACK cert, so nginx can listen on 443 from the very first
307	  //    second the account exists. Without this the account served HTTP-only until
308	  //    the SSL sweep ran, and any visitor hitting https:// got ERR_CONNECTION_REFUSED
309	  //    while the panel already said "active" (the kaymo failure). Idempotent: only
310	  //    generated if absent. Key is 600 root; the whole dir is root-owned + off the
311	  //    tenant tree, so a tenant can never read or swap its own TLS key.
312	  const ssCertDir = selfSignedCertDir(u);
313	  await run(
314	    conn,
315	    "self-signed fallback cert",
316	    `mkdir -p ${ssCertDir} && chmod 700 ${ssCertDir} && ` +
317	      `if [ ! -s ${ssCertDir}/fullchain.pem ] || [ ! -s ${ssCertDir}/privkey.pem ]; then ` +
318	      `openssl req -x509 -newkey rsa:2048 -nodes -keyout ${ssCertDir}/privkey.pem -out ${ssCertDir}/fullchain.pem ` +
319	      `-days 3650 -subj "/CN=${d}" -addext "subjectAltName=DNS:${d},DNS:www.${d}"; fi && ` +
320	      `chown -R root:root ${ssCertDir} && chmod 600 ${ssCertDir}/privkey.pem && chmod 644 ${ssCertDir}/fullchain.pem`,
321	  );
322	
323	  // 5. Name-based vhost — ALWAYS listens on 443, using the self-signed fallback
324	  //    until the SSL sweep swaps in the real Let's Encrypt cert.
325	  await installVhost(conn, u, renderHostingVhost(u, d, webroot, sock, { certDir: ssCertDir, real: false }));
326	
327	  // 6. Chrooted SFTP — sshd -t GUARDED so a bad config can never lock out the box.
328	  const sftpConf = [
329	    `Match User ${u}`,
330	    `    ChrootDirectory ${home}`,
331	    `    ForceCommand internal-sftp`,
332	    `    AllowTcpForwarding no`,
333	    `    X11Forwarding no`,
334	  ].join("\n");
335	  const sshdFile = `/etc/ssh/sshd_config.d/nxeon-${u}.conf`;
336	  await run(
337	    conn,
338	    "sftp chroot (guarded)",
339	    // Write to a temp include, validate the WHOLE sshd config, and only then move
340	    // it into place + reload. If sshd -t fails, discard — never reload a broken config.
341	    `mkdir -p /etc/ssh/sshd_config.d && cat > ${sshdFile}.new <<'SSHD'\n${sftpConf}\nSSHD\n` +
342	      `cp -f ${sshdFile}.new ${sshdFile} && if sshd -t 2>/dev/null; then systemctl reload ssh 2>/dev/null || systemctl reload sshd; else rm -f ${sshdFile}; echo 'sshd -t rejected the chroot block — SFTP not enabled, box untouched'; fi; rm -f ${sshdFile}.new`,
343	  );
344	}
